// ─────────────────────────────────────────────────────────────────────
// Node: Verify Signature & Normalize Intent   Mode: Run Once for All Items
// Repo: n8n-6sense-zoominfo-intent-spike-hubspot-alert-engine · dhRobin Systems
// Authentication (fails closed):
//   hmac_sha256     (default) X-Intent-Signature: sha256=HMAC(secret, "<ts>.<raw body>")
//                   with X-Intent-Timestamp inside the replay window. Used by the
//                   relay that forwards 6sense or ZoomInfo intent to n8n.
//   zoominfo_token  (opt-in)  ZoomInfo's own webhooks send a static token in
//                   x-zoominfo-token; compared in constant time.
// Normalisation: 4 payload shapes → one item per account with a clean domain,
// tracked topics (0-100), score deltas, buying-stage transition and a surge
// decision. Cooldown/escalation rules suppress repeat alerts.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const helpers = this.helpers;
let crypto = null;
try { crypto = require('crypto'); } catch (error) { crypto = null; }

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const PERSIST = !SANDBOX_MODE && !DRY_RUN;
// Sandbox accepts both methods so the ZoomInfo token fixture runs; live defaults to HMAC only.
const AUTH_MODES = new Set(csv('INTENT_AUTH_MODES', SANDBOX_MODE ? 'hmac_sha256,zoominfo_token' : 'hmac_sha256').map((m) => m.toLowerCase()));
const SIG_HEADER = env('INTENT_SIGNATURE_HEADER', 'x-intent-signature').toLowerCase();
const TS_HEADER = env('INTENT_TIMESTAMP_HEADER', 'x-intent-timestamp').toLowerCase();
const TOLERANCE = Math.max(30, num('INTENT_SIGNATURE_TOLERANCE_SECONDS', 300));
const SANDBOX_SECRET = 'sandbox-fictional-intent-secret-not-for-production';
const SANDBOX_ZI = 'sandbox-fictional-zoominfo-verification-value';
const SECRET = env('INTENT_WEBHOOK_SECRET', '') || (SANDBOX_MODE ? SANDBOX_SECRET : '');
const ZI_TOKEN = env('ZOOMINFO_WEBHOOK_TOKEN', '') || (SANDBOX_MODE ? SANDBOX_ZI : '');
const THRESHOLD = num('INTENT_SCORE_THRESHOLD', 70);
const MIN_DELTA = num('MIN_SCORE_DELTA', 15);
const TRACKED = csv('TRACKED_TOPICS', '').map((t) => t.toLowerCase());
const SURGE_STAGES = csv('SURGE_BUYING_STAGES', 'Decision,Purchase').map((s) => s.toLowerCase());
const COOLDOWN_H = Math.max(0, num('ALERT_COOLDOWN_HOURS', 72));
const MAX_ACCOUNTS = Math.max(1, num('MAX_ACCOUNTS_PER_DELIVERY', 25));
const EXCLUDED = new Set(['gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com', 'yahoo.com', 'icloud.com', 'me.com', 'aol.com', 'proton.me', 'protonmail.com', 'gmx.com',
  ...csv('EXCLUDED_DOMAINS', 'YOUR_COMPANY_DOMAIN.example').map((d) => d.toLowerCase())]);
const STAGE_ORDER = ['target', 'awareness', 'consideration', 'decision', 'purchase'];

let runId;
try { runId = 'int_' + crypto.randomUUID(); } catch (error) { runId = 'int_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }
const run = { runId, startedAt: new Date().toISOString(), mode: SANDBOX_MODE ? 'sandbox' : DRY_RUN ? 'dry_run' : 'live', sandboxMode: SANDBOX_MODE, dryRun: DRY_RUN };

const items = $input.all();
const sharedFixtures = SANDBOX_MODE ? ((items.find((i) => i.json.sandboxFixtures) || { json: {} }).json.sandboxFixtures || null) : null;

const sha = (s) => crypto.createHash('sha256').update(String(s)).digest();
const safeEqual = (a, b) => !!crypto && typeof a === 'string' && typeof b === 'string' && a.length > 0 && b.length > 0 && crypto.timingSafeEqual(sha(a), sha(b));

function authenticate(headers, raw) {
  if (!crypto) return { ok: false, reason: 'crypto_module_unavailable' };
  if (headers['x-zoominfo-token'] !== undefined && AUTH_MODES.has('zoominfo_token')) {
    if (!ZI_TOKEN) return { ok: false, method: 'zoominfo_token', reason: 'zoominfo_token_not_configured' };
    return safeEqual(headers['x-zoominfo-token'], ZI_TOKEN) ? { ok: true, method: 'zoominfo_token' } : { ok: false, method: 'zoominfo_token', reason: 'zoominfo_token_mismatch' };
  }
  if (!AUTH_MODES.has('hmac_sha256')) return { ok: false, method: 'none', reason: 'no_accepted_auth_method' };
  if (!SECRET) return { ok: false, method: 'hmac_sha256', reason: 'webhook_secret_not_configured' };
  const provided = String(headers[SIG_HEADER] || '').replace(/^sha256=/i, '').trim();
  const ts = String(headers[TS_HEADER] || '').trim();
  if (!provided) return { ok: false, method: 'hmac_sha256', reason: 'signature_header_missing' };
  if (!/^\d{10,13}$/.test(ts)) return { ok: false, method: 'hmac_sha256', reason: 'timestamp_header_missing' };
  const digest = crypto.createHmac('sha256', SECRET).update(`${ts}.${raw}`, 'utf8').digest();
  if (!(safeEqual(provided.toLowerCase(), digest.toString('hex')) || safeEqual(provided, digest.toString('base64')))) return { ok: false, method: 'hmac_sha256', reason: 'signature_mismatch' };
  const tsSec = ts.length > 10 ? Math.floor(Number(ts) / 1000) : Number(ts);
  // Fixtures carry fixed timestamps, so the replay window is enforced outside sandbox only.
  if (!SANDBOX_MODE && Math.abs(Date.now() / 1000 - tsSec) > TOLERANCE) return { ok: false, method: 'hmac_sha256', reason: 'timestamp_outside_tolerance' };
  return { ok: true, method: 'hmac_sha256' };
}

const cleanDomain = (v) => {
  if (!v) return null;
  let s = String(v).trim().toLowerCase();
  if (s.includes('@')) s = s.split('@').pop();
  s = s.replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split(/[/?#:]/)[0].replace(/\.$/, '');
  return /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(s) ? s : null;
};
const score = (v) => { const n = Number(v); return Number.isFinite(n) ? Math.max(0, Math.min(100, Math.round(n))) : null; };
const stageName = (v) => { if (!v) return null; const s = String(v).trim().toLowerCase(); return STAGE_ORDER.includes(s) ? s[0].toUpperCase() + s.slice(1) : String(v).trim().slice(0, 40); };
const topic = (name, s, extra = {}) => ({ topic: String(name || '').trim().slice(0, 120), category: extra.category ? String(extra.category).slice(0, 80) : null, score: score(s),
  previousScore: score(extra.previousScore), trend: Number.isFinite(Number(extra.trend)) ? Number(extra.trend) : null, strength: extra.strength ? String(extra.strength).slice(0, 20) : null,
  isNew: extra.isNew === true, signalDate: extra.signalDate || null });

// ── Payload shapes ─────────────────────────────────────────────────────
function parseAccounts(b, authMethod) {
  // A · ZoomInfo webhook envelope: { webhookDetails, data: [ company records ] }
  if (b && b.webhookDetails && Array.isArray(b.data)) {
    return { provider: 'zoominfo', shape: 'zoominfo_webhook', accounts: b.data.map((r) => ({
      providerAccountId: r.id != null ? String(r.id) : null, name: r.name || null, domain: cleanDomain(r.website || r.domain),
      topics: (r.intentSignals || r.intent || r.topics || []).map((s) => topic(s.topic, s.signalScore ?? s.score, { category: s.category, trend: s.trend, strength: s.audienceStrength, isNew: s.newSignal, signalDate: s.signalDate })),
      buyingStage: null, previousBuyingStage: null, accountScore: null, previousAccountScore: null, observedAt: null })) };
  }
  // B · ZoomInfo Intent API records forwarded by a relay: { data: [ { type: 'Intent', attributes: {...} } ] }
  if (b && Array.isArray(b.data) && b.data.some((r) => r && r.attributes && r.attributes.topic)) {
    const byCo = {};
    for (const r of b.data) {
      const a = r.attributes || {}; const co = a.company || {};
      const key = cleanDomain(co.website || co.domain) || `zi:${co.id}`;
      const acc = (byCo[key] = byCo[key] || { providerAccountId: co.id != null ? String(co.id) : null, name: co.name || null, domain: cleanDomain(co.website || co.domain), topics: [], buyingStage: null, previousBuyingStage: null, accountScore: null, previousAccountScore: null, observedAt: null });
      acc.topics.push(topic(a.topic, a.signalScore, { category: a.category, trend: a.trend, strength: a.audienceStrength, isNew: a.newSignal, signalDate: a.signalDate }));
      if (a.signalDate && (!acc.observedAt || a.signalDate > acc.observedAt)) acc.observedAt = a.signalDate;
    }
    return { provider: 'zoominfo', shape: 'zoominfo_intent_api', accounts: Object.values(byCo) };
  }
  // C · 6sense relay: { source: '6sense', accounts: [ ... ] }
  if (b && /6sense|sixsense/i.test(String(b.source || '')) && Array.isArray(b.accounts)) {
    return { provider: '6sense', shape: 'sixsense_relay', accounts: b.accounts.map((a) => ({
      providerAccountId: a.accountId != null ? String(a.accountId) : null, name: a.name || a.accountName || null, domain: cleanDomain(a.domain || a.website),
      topics: (a.intentKeywords || a.keywords || []).map((k) => (typeof k === 'string' ? topic(k, a.intentScore) : topic(k.keyword || k.topic, k.score ?? a.intentScore, { previousScore: k.previousScore, isNew: k.isNew }))),
      buyingStage: stageName(a.buyingStage), previousBuyingStage: stageName(a.previousBuyingStage), accountScore: score(a.intentScore), previousAccountScore: score(a.previousIntentScore),
      profileFit: a.profileFit || null, observedAt: a.updatedAt || null })) };
  }
  // D · Normalised relay format: { events: [ ... ] }
  if (b && Array.isArray(b.events)) {
    return { provider: String(b.source || 'relay').toLowerCase().slice(0, 30), shape: 'normalized', accounts: b.events.map((e) => ({
      providerAccountId: e.accountId != null ? String(e.accountId) : null, name: e.accountName || e.name || null, domain: cleanDomain(e.domain || e.website),
      topics: (e.topics || []).map((t) => topic(t.topic, t.score, { previousScore: t.previousScore, trend: t.trend, strength: t.strength, isNew: t.isNew, category: t.category })),
      buyingStage: stageName(e.buyingStage), previousBuyingStage: stageName(e.previousBuyingStage), accountScore: score(e.accountScore), previousAccountScore: score(e.previousAccountScore), observedAt: e.observedAt || null })) };
  }
  return null;
}

function evaluate(acc) {
  const topics = acc.topics.filter((t) => t.topic && t.score !== null && (!TRACKED.length || TRACKED.includes(t.topic.toLowerCase())));
  for (const t of topics) t.delta = t.previousScore !== null ? t.score - t.previousScore : t.trend;
  const surging = topics.filter((t) => t.score >= THRESHOLD && (t.isNew || (t.delta !== null && t.delta >= MIN_DELTA))).sort((a, b) => b.score - a.score);
  const iFrom = STAGE_ORDER.indexOf(String(acc.previousBuyingStage || '').toLowerCase());
  const iTo = STAGE_ORDER.indexOf(String(acc.buyingStage || '').toLowerCase());
  const stageAdvanced = iTo > -1 && iTo > iFrom && acc.previousBuyingStage != null;
  const stageSurge = stageAdvanced && SURGE_STAGES.includes(String(acc.buyingStage).toLowerCase());
  const accountDelta = acc.accountScore !== null && acc.previousAccountScore !== null ? acc.accountScore - acc.previousAccountScore : null;
  const accountSurge = acc.accountScore !== null && acc.accountScore >= THRESHOLD && accountDelta !== null && accountDelta >= MIN_DELTA;
  const peak = Math.max(acc.accountScore || 0, ...topics.map((t) => t.score));
  const reasons = [];
  if (surging.length) reasons.push(`${surging.length} topic(s) ≥ ${THRESHOLD} and new or up ≥ ${MIN_DELTA}`);
  if (stageSurge) reasons.push(`buying stage ${acc.previousBuyingStage} → ${acc.buyingStage}`);
  if (accountSurge) reasons.push(`account intent score up ${accountDelta} to ${acc.accountScore}`);
  return { topics: topics.sort((a, b) => b.score - a.score).slice(0, 10), surgingTopics: surging.slice(0, 5).map((t) => t.topic), isSurge: reasons.length > 0, reasons, peakScore: peak,
    stageTransition: acc.previousBuyingStage || acc.buyingStage ? { from: acc.previousBuyingStage, to: acc.buyingStage, advanced: stageAdvanced, surge: stageSurge } : null, accountDelta };
}

// ── Ledger (cooldown + escalation) ────────────────────────────────────
const staticData = $getWorkflowStaticData('global');
const ledger = PERSIST ? (staticData.intentAlertLedger = staticData.intentAlertLedger || {}) : JSON.parse(JSON.stringify(staticData.intentAlertLedger || {}));
const nowMs = Date.now();
for (const [k, v] of Object.entries(ledger)) if (!v || nowMs - v.at > Math.max(COOLDOWN_H, 1) * 3600000 * 4) delete ledger[k];
const seenThisRun = {};

const out = [];
for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const headers = {};
  for (const [k, v] of Object.entries(item.json.headers || {})) headers[String(k).toLowerCase()] = Array.isArray(v) ? String(v[0]) : String(v);
  let raw = null;
  if (item.binary && item.binary.data) { try { raw = (await helpers.getBinaryDataBuffer(index, 'data')).toString('utf8'); } catch (e) { raw = null; } }
  let body = item.json.body;
  if ((!body || (typeof body === 'object' && !Object.keys(body).length)) && raw) { try { body = JSON.parse(raw); } catch (e) { body = null; } }
  if (raw === null) raw = typeof body === 'string' ? body : JSON.stringify(body ?? {});
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  const deliveryId = String(headers['x-intent-delivery-id'] || (body && (body.deliveryId || (body.webhookDetails && body.webhookDetails.id))) || `delivery-${index + 1}`).slice(0, 80);
  const base = { run, sandboxFixtures: sharedFixtures, deliveryId };

  const auth = authenticate(headers, raw);
  if (!auth.ok) { out.push({ json: { ...base, kind: 'rejected', reason: auth.reason, authMethod: auth.method || null } }); continue; }
  const parsed = parseAccounts(body, auth.method);
  if (!parsed) { out.push({ json: { ...base, kind: 'ignored', reason: 'unrecognised_payload_shape', authMethod: auth.method } }); continue; }
  if (parsed.accounts.length > MAX_ACCOUNTS) parsed.accounts = parsed.accounts.slice(0, MAX_ACCOUNTS);

  for (const acc of parsed.accounts) {
    const signal = { provider: parsed.provider, shape: parsed.shape, providerAccountId: acc.providerAccountId, accountName: acc.name ? String(acc.name).slice(0, 120) : null, domain: acc.domain,
      buyingStage: acc.buyingStage, accountScore: acc.accountScore, profileFit: acc.profileFit || null, observedAt: acc.observedAt };
    const ignore = (reason, extra = {}) => out.push({ json: { ...base, kind: 'ignored', reason, authMethod: auth.method, signal, ...extra } });
    if (!acc.domain) { ignore('domain_missing_or_invalid'); continue; }
    if (EXCLUDED.has(acc.domain)) { ignore('excluded_domain'); continue; }
    const ev = evaluate(acc);
    signal.topics = ev.topics; signal.surgingTopics = ev.surgingTopics; signal.peakScore = ev.peakScore; signal.stageTransition = ev.stageTransition; signal.accountDelta = ev.accountDelta;
    if (!ev.topics.length && signal.accountScore === null && !ev.stageTransition) { ignore('no_tracked_intent'); continue; }
    if (!ev.isSurge) { ignore('below_surge_threshold', { surge: { peakScore: ev.peakScore } }); continue; }

    const prev = seenThisRun[acc.domain] || ledger[acc.domain];
    let escalation = false;
    if (prev && nowMs - prev.at < COOLDOWN_H * 3600000) {
      const stageUp = STAGE_ORDER.indexOf(String(acc.buyingStage || '').toLowerCase()) > STAGE_ORDER.indexOf(String(prev.stage || '').toLowerCase());
      const scoreUp = ev.peakScore - (prev.peakScore || 0) >= MIN_DELTA;
      if (!stageUp && !scoreUp) { ignore('cooldown_active', { cooldown: { hours: COOLDOWN_H, lastAlertAt: new Date(prev.at).toISOString() } }); continue; }
      escalation = true;
    }
    seenThisRun[acc.domain] = { at: nowMs, peakScore: ev.peakScore, stage: acc.buyingStage };
    out.push({ json: { ...base, kind: 'surge', authMethod: auth.method, signal, surge: { reasons: ev.reasons, escalation, peakScore: ev.peakScore } } });
  }
}
return out;

// ─────────────────────────────────────────────────────────────────────
// Node: Build Account Lookup                  Mode: Run Once for Each Item
// Builds the HubSpot company search for the normalised domain.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const TIER_PROP = env('HUBSPOT_TIER_PROPERTY', 'hs_ideal_customer_profile');
const d = $json.signal.domain;
return {
  json: {
    ...$json,
    lookup: {
      tierProperty: TIER_PROP,
      companySearch: {
        filterGroups: [
          { filters: [{ propertyName: 'domain', operator: 'EQ', value: d }] },
          { filters: [{ propertyName: 'domain', operator: 'EQ', value: `www.${d}` }] },
          { filters: [{ propertyName: 'hs_additional_domains', operator: 'CONTAINS_TOKEN', value: d }] },
        ],
        properties: ['name', 'domain', 'website', 'hs_additional_domains', 'hubspot_owner_id', TIER_PROP, 'hs_is_target_account', 'hs_num_open_deals', 'hs_lastmodifieddate'],
        limit: 10,
      },
    },
  },
};

// ─────────────────────────────────────────────────────────────────────
// Node: Simulate HubSpot Lookup (Sandbox)     Mode: Run Once for Each Item
// Answers the company, open-deal and open-task searches from fictional
// fixtures, in the CRM search response shape the live nodes return.
// ─────────────────────────────────────────────────────────────────────
const item = $json;
const fx = item.sandboxFixtures || {};
const d = item.signal.domain;
const norm = (v) => String(v || '').toLowerCase().replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split('/')[0];
const companies = (fx.companies || []).filter((c) => norm(c.properties.domain) === d || String(c.properties.hs_additional_domains || '').toLowerCase().split(/[;,\s]+/).includes(d));
const ok = (list) => ({ statusCode: 200, body: { total: list.length, results: list.map((r) => ({ id: r.id, properties: r.properties })) } });
const co = companies[0] || null;
const deals = co ? (fx.deals || []).filter((x) => x.companyId === co.id && x.properties.hs_is_closed !== 'true') : [];
const tasks = co ? (fx.tasks || []).filter((x) => x.companyId === co.id && x.properties.hs_task_status !== 'COMPLETED') : [];
return { json: { ...item, simulatedLookup: { company: ok(companies), deals: ok(deals), tasks: ok(tasks) } } };

// ─────────────────────────────────────────────────────────────────────
// Node: Pick Company & Build Searches         Mode: Run Once for Each Item
// Chooses the best company for the domain (exact primary domain first),
// then builds the open-deal and recent-task searches for it.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const TASK_WINDOW_DAYS = Math.max(1, num('TASK_DEDUPE_DAYS', 7));
const PIPELINES = csv('HUBSPOT_DEAL_PIPELINE_IDS', '');
const sandbox = !!($json && $json.simulatedLookup);
const ctx = sandbox ? $json : $('Build Account Lookup').item.json;
const res = sandbox ? $json.simulatedLookup.company : $json;
const d = ctx.signal.domain;
const tierProp = ctx.lookup.tierProperty;
const norm = (v) => String(v || '').toLowerCase().replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split('/')[0];

let companyLookup;
if (Number(res && res.statusCode) !== 200 || !res.body || !Array.isArray(res.body.results)) {
  companyLookup = { status: 'lookup_failed', httpStatus: (res && res.statusCode) || null };
} else {
  const ranked = res.body.results.map((c) => {
    const p = c.properties || {};
    const exact = norm(p.domain) === d || norm(p.website) === d;
    const extra = String(p.hs_additional_domains || '').toLowerCase().split(/[;,\s]+/).map(norm).includes(d);
    return { c, p, rank: (exact ? 100 : extra ? 50 : 0) + (p[tierProp] ? 8 : 0) + (String(p.hs_is_target_account) === 'true' ? 4 : 0) + (p.hubspot_owner_id ? 2 : 0) + (Number(p.hs_num_open_deals) > 0 ? 1 : 0), exact, extra };
  }).filter((x) => x.exact || x.extra).sort((a, b) => b.rank - a.rank);
  if (!ranked.length) companyLookup = { status: 'not_found' };
  else {
    const top = ranked[0];
    companyLookup = {
      status: 'found', matchedOn: top.exact ? 'primary_domain' : 'additional_domain', duplicateCount: ranked.filter((x) => x.exact).length,
      company: { id: String(top.c.id), name: top.p.name || null, domain: top.p.domain || null, ownerId: top.p.hubspot_owner_id || null, tierRaw: top.p[tierProp] || null,
        isTargetAccount: String(top.p.hs_is_target_account) === 'true', openDeals: Number(top.p.hs_num_open_deals || 0) },
    };
  }
}
const cid = companyLookup.company ? companyLookup.company.id : '0';
const dealFilters = [{ propertyName: 'associations.company', operator: 'EQ', value: cid }, { propertyName: 'hs_is_closed', operator: 'EQ', value: 'false' }];
if (PIPELINES.length) dealFilters.push({ propertyName: 'pipeline', operator: 'IN', values: PIPELINES });
const { simulatedLookup, ...rest } = ctx;
return {
  json: {
    ...rest,
    ...(sandbox ? { simulatedLookup } : {}),
    companyLookup,
    searches: {
      deals: { filterGroups: [{ filters: dealFilters }], properties: ['dealname', 'dealstage', 'pipeline', 'amount', 'closedate', 'hubspot_owner_id', 'hs_lastmodifieddate'],
        sorts: [{ propertyName: 'hs_lastmodifieddate', direction: 'DESCENDING' }], limit: 5 },
      tasks: { filterGroups: [{ filters: [{ propertyName: 'associations.company', operator: 'EQ', value: cid }, { propertyName: 'hs_task_status', operator: 'NEQ', value: 'COMPLETED' },
        { propertyName: 'hs_createdate', operator: 'GTE', value: String(Date.now() - TASK_WINDOW_DAYS * 86400000) }] }],
        properties: ['hs_task_subject', 'hs_task_status', 'hubspot_owner_id', 'hs_timestamp'], limit: 20 },
    },
